custom_css:
#chat {
    scrollbar-width: 12px;
    padding-bottom: 30px;
}

.mesAvatarWrapper {
    padding: 0px 10px;
    display: flex; 
    align-items: flex-start; 
}

.avatar {
    margin-top: 0px;
    width: 35px;
    height: 35px;
    border-radius: 50% !important;
    overflow: hidden;
    margin-bottom: 5px; 
}

.mesAvatarWrapper img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 0 !important;
}


}

.flex-container.alignItemsBaseline {
    flex-wrap: nowrap;
}

.mes_text {
    padding: 15px 15px;
    border-radius: 20px;
    display: inline-block; 
    margin-bottom: 5px; 
}


}

.mes {
    width: fit-content;
    display: flex; 
}

.mes_block {
    width: fit-content;
    width: 80%;
    display: flex; 
    flex-direction: column; 
    align-items: flex-start;  
    margin-top: 10px; 
}


.mes[is_user="false"] .mes_block {
    padding-left: 5px;
}

.mes[is_user="true"] .mes_block {
    padding-right: 5px;
    align-items: flex-end; 
}

.ch_name.flex-container.justifySpaceBetween {
    margin-bottom: 5px;
}

.mes[is_user="true"] {
    flex-direction: row-reverse;
    margin-left: auto;
}

.mes[is_user="true"] .mes_block .ch_name.flex-container.justifySpaceBetween {
    flex-direction: row-reverse;
    margin-left: auto;
}

.mes[is_user="true"] .mes_block .ch_name.flex-container.justifySpaceBetween .flex-container.flex1.alignitemscenter {
    flex-direction: row-reverse;
}

.mes[is_user="true"] .mes_block .ch_name.flex-container.justifySpaceBetween .flex-container.flex1.alignitemscenter .flex-container.alignItemsBaseline {
    flex-direction: row-reverse;
}


.mes[is_user="true"] .mes_block .mes_text {
    background-color: #131418;
}

.mes[is_user="false"] .mes_block .mes_text {
    background-color: #18191e;
}
